// Generates tft/ROUND2.md: the Editor edits that take the first Soft dark TFT to the safe-area layout
// with Homey icon fonts. Usage: bun design/round2.ts
import { DESIGN_PAGES, PAGES } from './layout';

// The first TFT used one MDI font for chips and tiles; they now use the Homey icon fonts.
const OLD_FONT: Record<string, string> = { F_HICON_S: 'F_ICON_S', F_HICON_L: 'F_ICON_L' };

export function round2Markdown(): string {
  const out: string[] = ['# Round 2: safe area, graphite background, Homey icons (generated — do not edit)', '',
    'Generated by `bun design/round2.ts`. Work in a copy: Save As `~/nspanel-tft/nspanel_soft_dark_r2.HMI`.', '',
    '## Steps', '',
    '1. **Font:** copy `tft/fonts/NSPanelHomeyIcons.ttf` into the bottle\'s `C:\\windows\\Fonts`, restart Nextion Editor.',
    '2. **Generate two fonts** (Tools → Font Generator): font *NSPanel Homey Icons*, encoding **utf-8**, anti-aliasing on,',
    '   characters: **Specify**, paste the contents of `tft/fonts/homey-icons-chars.txt`.',
    '   - height **24** → save as `homey24` (this is `F_HICON_S`)',
    '   - height **32** → save as `homey32` (this is `F_HICON_L`)',
    '   Add both to the project.',
    '3. **Replace the 8 pictures**: in the Picture panel select each existing Soft dark picture and use **Replace** with the',
    '   file of the same name from `tft/assets/` (the ids must stay the same: 48–55).',
    '4. **Edit the components** listed below (x / w, and the icon fonts of `chips` and `i01`–`i08`).',
    '5. **Calendar:** set the `font` of `t01`–`t08` to `inter_body17` (the app no longer switches fonts at runtime).',
    '6. Compile (0 errors), File → TFT file output → `~/nspanel-tft/nspanel_soft_dark_r2.tft`.',
    '7. Send Claude a screenshot of the **Fonts** panel (ids and names).', ''];
  for (const page of PAGES) {
    const before = DESIGN_PAGES.find((p) => p.name === page.name)!;
    const rows: string[] = [];
    for (const c of page.components) {
      const o = before.components.find((x) => x.name === c.name)!;
      const changes: string[] = [];
      if (o.x !== c.x) changes.push(`x ${o.x} → **${c.x}**`);
      if (o.w !== c.w) changes.push(`w ${o.w} → **${c.w}**`);
      if (OLD_FONT[c.font]) changes.push(`font → **${c.font}**`);
      if (changes.length) rows.push(`| ${c.name} | Text | ${changes.join(', ')} |`);
    }
    for (const h of page.hotspots) {
      const o = before.hotspots.find((x) => x.name === h.name)!;
      const changes: string[] = [];
      if (o.x !== h.x) changes.push(`x ${o.x} → **${h.x}**`);
      if (o.w !== h.w) changes.push(`w ${o.w} → **${h.w}**`);
      if (changes.length) rows.push(`| ${h.name} | Hotspot | ${changes.join(', ')} |`);
    }
    if (!rows.length) continue;
    out.push(`## ${page.name}`, '', '| Component | Type | Change |', '|---|---|---|', ...rows, '');
  }
  return out.join('\n');
}

if (import.meta.main) {
  await Bun.write('tft/ROUND2.md', round2Markdown());
  console.log('wrote tft/ROUND2.md');
}
